// CommitQueryService — read path for the new architecture.
//
// Plan §"CommitQueryService":
//   - Never inner-join repo_branch_commits in serving queries — left-join
//     and degrade gracefully if the cache is incomplete.
//   - findCommitBySha is the model: SHA in repo_commits resolves; empty
//     branches list renders, no 404.
//   - Reads still detect drift and log it for visibility, but do NOT
//     enqueue reconcile from the read path. The hourly cron
//     (cron.ts:runHourlyGitSourceCron) reconciles stale branches, and
//     webhooks reconcile on push. See note below.

import type { Env } from "../../env"
import type { CheckpointWithCommit, CommitListItem, CommitLocation } from "../db/checkpoints"
import type { Db } from "../db/db-types"

const LOG_PREFIX = "[git-source/query]"

function log(event: string, data: Record<string, unknown>): void {
  console.log(`${LOG_PREFIX} ${event}`, JSON.stringify(data))
}

// Read-path reconcile fan-out is disabled. The in-isolate dedupe doesn't
// span the Worker fleet, so multiple isolates each enqueued the same
// reconcile concurrently against the same hot SHAs — the dominant
// trigger of the 2026-05-19 repo_commits deadlock spike. Drift is now
// picked up by the hourly cron + webhook push, which is the source of
// truth post-May-5 git-source cutover.
//
// To re-enable, restore the body of emitDriftOnce from git history (and
// the enqueueReconcileBranch/errorString imports). Keep the drift_*
// log lines either way — they're how we measure how often this matters.
function emitDriftOnce(
  _env: Env,
  _args: { repoId: string; branch: string; reason: "drift" | "audit"; source: string },
): void {}

export interface CommitQueryService {
  /**
   * Find a commit by its SHA across the whole repo. Returns null only when
   * the SHA isn't in repo_commits at all — empty branches list does NOT
   * cause 404.
   */
  findCommitBySha(args: {
    repoId: string
    repoFullName: string
    commitSha: string
    defaultBranch?: string
  }): Promise<CommitLocation | null>

  /**
   * List commits for a branch, paged + windowed. Detects sync state with
   * stale TTL and emits a single drift signal per pair if found.
   */
  listCommitsForBranch(args: {
    repoId: string
    repoFullName: string
    branch: string
    limit?: number
    offset?: number
    since?: string
    until?: string
  }): Promise<CommitListItem[]>

  /** Checkpoints linked to a branch. Same drift detection rules as listCommitsForBranch. */
  listCheckpointsForBranch(args: {
    repoId: string
    repoFullName: string
    branch: string
    limit?: number
  }): Promise<CheckpointWithCommit[]>
}

const STALE_BRANCH_TTL_MS = 24 * 60 * 60 * 1000 // 24h: matches reconciliation cron cadence

async function maybeEmitEmptyBranchDrift(
  env: Env,
  db: Db,
  args: {
    repoId: string
    repoFullName: string
    branch: string
    sourcePrefix: string
    empty: boolean
  },
): Promise<void> {
  if (!args.empty) return
  const state = await db.checkpoints.getBranchSyncState(args.repoId, args.branch).catch(() => null)
  if (!state) {
    log("drift_unsynced_branch", {
      repoId: args.repoId,
      repoFullName: args.repoFullName,
      branch: args.branch,
    })
    emitDriftOnce(env, {
      repoId: args.repoId,
      branch: args.branch,
      reason: "drift",
      source: `${args.sourcePrefix}:no_state`,
    })
    return
  }
  if (
    state.last_synced_at &&
    new Date(state.last_synced_at).getTime() < Date.now() - STALE_BRANCH_TTL_MS
  ) {
    log("drift_stale_branch", {
      repoId: args.repoId,
      repoFullName: args.repoFullName,
      branch: args.branch,
    })
    emitDriftOnce(env, {
      repoId: args.repoId,
      branch: args.branch,
      reason: "drift",
      source: `${args.sourcePrefix}:ttl_exceeded`,
    })
  }
}

export function createCommitQueryService(env: Env, db: Db): CommitQueryService {
  return {
    async findCommitBySha({ repoId, repoFullName, commitSha, defaultBranch }) {
      const location = await db.checkpoints.findCommitBySha(repoId, commitSha, defaultBranch)
      if (!location) return null

      // Drift signal: SHA is canonical (in repo_commits) but the default-branch
      // reachability projection is incomplete. Plan §"On-read drift" — broad signals.
      if (
        defaultBranch &&
        location.expected_on_default_branch &&
        !location.branches.includes(defaultBranch)
      ) {
        log("drift_orphan_commit", { repoId, repoFullName, commitSha })
        emitDriftOnce(env, {
          repoId,
          branch: defaultBranch,
          reason: "drift",
          source: "findCommitBySha:missing_default_branch",
        })
      }
      return location
    },

    async listCommitsForBranch({ repoId, repoFullName, branch, limit, offset, since, until }) {
      const commits = await db.checkpoints.getCommitsForBranch(repoId, branch, {
        limit,
        offset,
        since,
        until,
      })
      await maybeEmitEmptyBranchDrift(env, db, {
        repoId,
        repoFullName,
        branch,
        sourcePrefix: "listCommitsForBranch",
        empty: commits.length === 0,
      })
      return commits
    },

    async listCheckpointsForBranch({ repoId, repoFullName, branch, limit }) {
      const checkpoints = await db.checkpoints.getForBranch(repoId, branch, { limit })
      // Same drift logging logic as commit list.
      await maybeEmitEmptyBranchDrift(env, db, {
        repoId,
        repoFullName,
        branch,
        sourcePrefix: "listCheckpointsForBranch",
        empty: checkpoints.length === 0,
      })
      return checkpoints
    },
  }
}

