import { createFileRoute, notFound } from "@tanstack/react-router"

import { resolveCommitQueryOptions } from "@/domains/platform/checkpoints/hooks/useCommitsQuery"
import { CommitDetailPage } from "@/domains/platform/checkpoints/pages/CommitDetailPage"
import { repoAccessLoader } from "@/domains/platform/commits/routeConfig"
import { ApiError } from "@/lib/api"

/**
 * Commit detail route.
 *
 * The optional `{-$branch}` path segment is a sharing context indicator: a
 * single commit can live on multiple branches, so the canonical identity is
 * just the SHA. When a user shares a link from a specific branch we want to
 * preserve that context in the URL (so the recipient sees the same
 * breadcrumb), without making the branch part of the commit's identity.
 *
 * Both forms resolve to the same page:
 *   /gh/$org/$repo/commit/$commitSha
 *   /gh/$org/$repo/commit/$commitSha/$branch
 *
 * If the branch turns out to be stale (the commit isn't / no longer is on
 * that branch), the page strips the segment and redirects to the canonical
 * branchless URL — see `CommitDetailPage`.
 */
export const Route = createFileRoute("/_app/_repo/gh/$org/$repo/commit/$commitSha/{-$branch}")({
  loader: async ({ context, params, location }) => {
    const [repoAccessResult, resolveCommitResult] = await Promise.allSettled([
      repoAccessLoader({ context, params, location }),
      context.queryClient.ensureQueryData(
        resolveCommitQueryOptions(params.org, params.repo, params.commitSha),
      ),
    ])

    if (repoAccessResult.status === "rejected") throw repoAccessResult.reason
    if (resolveCommitResult.status === "rejected") {
      const error = resolveCommitResult.reason
      // The commits/resolve endpoint 404s when the SHA isn't in repo_branch_commits
      // — surface the dedicated not-found page instead of the generic 500
      // fallback. Other errors keep flowing to the route's errorComponent.
      if (error instanceof ApiError && error.status === 404) {
        throw notFound()
      }
      throw error
    }
  },
  component: CommitRoute,
})

function CommitRoute() {
  const { org, repo, commitSha, branch } = Route.useParams()
  return <CommitDetailPage org={org} repo={repo} commitSha={commitSha} branchHint={branch} />
}
